import{_ as s,C as n,o as i,c as r,j as t,a as o,E as d,a2 as l}from"./chunks/framework.Di-jvWLj.js";const w=JSON.parse('{"title":"GitHub App","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/github-app.md","filePath":"deployment/github-app.md","lastUpdated":1792243762000}'),p={name:"deployment/github-app.md"},h={id:"github-app",tabindex:"-1"};function c(u,e,g,b,m,f){const a=n("Badge");return i(),r("div",null,[t("h1",h,[e[0]||(e[0]=o("GitHub App ",-1)),d(a,{type:"warning",text:"Planned"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#github-app","aria-label":'Permalink to "GitHub App <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=l('<div class="warning custom-block"><p class="custom-block-title">Planned</p><p><code>@chamberu/github</code> is planned. Names and options may change.</p></div><h2 id="one-app-per-agent-repository" tabindex="-1">One App per agent repository <a class="header-anchor" href="#one-app-per-agent-repository" aria-label="Permalink to &quot;One App per agent repository&quot;">​</a></h2><p>Each agent repository (and so each image) gets its own GitHub App, with its own webhook URL, App credentials and Secret. There is no shared intake router: an App&#39;s webhooks go straight to the app that owns it.</p><p>The App needs the permissions its tools use (for triage: issues read and write, metadata read, contents read) and subscribes to the events its triggers name.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>The planned connector mounts <code>POST /webhooks/github</code> into the HTTP app and:</p><ol><li>verifies <code>X-Hub-Signature-256</code> against the raw body and rejects anything else with <code>401</code>,</li><li>matches the event and action (<code>issues.opened</code>, <code>pull_request.synchronize</code>, ...) against the agents&#39; <code>github.webhook()</code> triggers,</li><li>ignores events sent by the App itself, so the agent does not trigger itself,</li><li>dispatches with the delivery id (<code>X-GitHub-Delivery</code>) as the idempotency key and, by default, <code>&lt;owner&gt;/&lt;repo&gt;#&lt;number&gt;</code> as the concurrency key,</li><li>answers <code>202</code> right away; the run happens asynchronously.</li></ol><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Installation tokens are short-lived, cached per installation until they expire and never logged. Read tools cover issues, labels, search, pull requests, files and releases. Write tools are <a href="/guide/effect-tools">effect tools</a>:</p><ul><li>adding labels is naturally idempotent,</li><li>comments embed an <a href="/guide/effect-tools#the-crash-window"><code>effectMarker</code></a> and <code>alreadyApplied</code> searches for it before posting, so a crash between posting and recording does not post twice,</li><li>closing an issue is meant to sit behind an <a href="/guide/approvals">approval</a>.</li></ul><p>Sandboxes never get the App&#39;s credentials. When a tool must push, the connector creates a short-lived token scoped to one repository.</p><h2 id="what-works-today" tabindex="-1">What works today <a class="header-anchor" href="#what-works-today" aria-label="Permalink to &quot;What works today&quot;">​</a></h2><p>You can already write GitHub tools as effect tools with your own Octokit client and dispatch runs from your own webhook handler, using the delivery id as <code>idempotencyKey</code>. The <a href="/guide/effect-tools">effect tools</a> page shows the comment pattern.</p>',13))])}const k=s(p,[["render",c]]);export{w as __pageData,k as default};
